import { useMemo } from "react";

type CartItem = {
  id: string;
  price: number;
  quantity: number;
};

type CartTotalProps = {
  items: CartItem[];
};

export const CartTotal = ({ items }: CartTotalProps) => {
  const total = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items],
  );

  return (
    <div className="cart-total">
      <span>Total:</span>
      <span data-testid="cart-total-amount">{total}</span>
    </div>
  );
};

